arguments.command:
source /opt/miniconda3/bin/activate testbed && python -c "
import locale
print('Locale settings:')
for cat in [locale.LC_ALL, locale.LC_COLLATE, locale.LC_CTYPE, locale.LC_MONETARY, locale.LC_NUMERIC, locale.LC_TIME]:
    try:
        print(f'  {cat}: {locale.getlocale(cat)}')
    except Exception as e:
        print(f'  {cat}: Error - {e}')
"

